create or replace function public.business_can_manage(p_business_id uuid) returns boolean language sql security definer set search_path=public,pg_temp as $$ select exists(select 1 from business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role in ('owner','admin')) or coalesce((select is_admin from profiles where id=auth.uid()),false); $$;
create or replace function public.business_create_promotion(p_business_id uuid,p_title text,p_description text default null,p_discount numeric default null,p_location_id uuid default null,p_starts_at timestamptz default now(),p_ends_at timestamptz default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not public.business_can_manage(p_business_id) then raise exception 'Business admin permission required'; end if; insert into promotions(business_id,title,description,discount,location_id,starts_at,ends_at,active) values(p_business_id,p_title,p_description,p_discount,p_location_id,p_starts_at,p_ends_at,true) returning id into v_id; return v_id; end; $$;
create or replace function public.business_set_promotion_active(p_business_id uuid,p_promotion_id uuid,p_active boolean) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_can_manage(p_business_id) then raise exception 'Business admin permission required'; end if; update promotions set active=p_active where id=p_promotion_id and business_id=p_business_id; return found; end; $$;
create or replace function public.business_create_location(p_business_id uuid,p_name text,p_address text default null,p_city text default null,p_state text default null,p_lat numeric default null,p_lng numeric default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not public.business_can_manage(p_business_id) then raise exception 'Business admin permission required'; end if; insert into locations(business_id,name,address,city,state,latitude,longitude,is_active) values(p_business_id,p_name,p_address,p_city,p_state,p_lat,p_lng,true) returning id into v_id; return v_id; end; $$;
create or replace function public.business_set_location_active(p_business_id uuid,p_location_id uuid,p_active boolean) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_can_manage(p_business_id) then raise exception 'Business admin permission required'; end if; update locations set is_active=p_active where id=p_location_id and business_id=p_business_id; return found; end; $$;
create or replace function public.business_create_event(p_business_id uuid,p_title text,p_description text default null,p_location_id uuid default null,p_event_date date default null,p_event_time time default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not public.business_can_manage(p_business_id) then raise exception 'Business admin permission required'; end if; insert into business_events(business_id,title,description,location_id,event_date,event_time) values(p_business_id,p_title,p_description,p_location_id,p_event_date,p_event_time) returning id into v_id; return v_id; end; $$;
create or replace function public.business_set_event(p_business_id uuid,p_event_id uuid,p_title text,p_description text,p_event_date date,p_event_time time,p_location_id uuid) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_can_manage(p_business_id) then raise exception 'Business admin permission required'; end if; update business_events set title=p_title,description=p_description,event_date=p_event_date,event_time=p_event_time,location_id=p_location_id where id=p_event_id and business_id=p_business_id; return found; end; $$;
revoke all on function public.business_can_manage(uuid) from public; grant execute on function public.business_can_manage(uuid) to authenticated;
revoke all on function public.business_create_promotion(uuid,text,text,numeric,uuid,timestamptz,timestamptz) from public; grant execute on function public.business_create_promotion(uuid,text,text,numeric,uuid,timestamptz,timestamptz) to authenticated;
revoke all on function public.business_set_promotion_active(uuid,uuid,boolean) from public; grant execute on function public.business_set_promotion_active(uuid,uuid,boolean) to authenticated;
revoke all on function public.business_create_location(uuid,text,text,text,text,numeric,numeric) from public; grant execute on function public.business_create_location(uuid,text,text,text,text,numeric,numeric) to authenticated;
revoke all on function public.business_set_location_active(uuid,uuid,boolean) from public; grant execute on function public.business_set_location_active(uuid,uuid,boolean) to authenticated;
revoke all on function public.business_create_event(uuid,text,text,uuid,date,time) from public; grant execute on function public.business_create_event(uuid,text,text,uuid,date,time) to authenticated;
revoke all on function public.business_set_event(uuid,uuid,text,text,date,time,uuid) from public; grant execute on function public.business_set_event(uuid,uuid,text,text,date,time,uuid) to authenticated;
